import hashlib,json,os,pathlib,subprocess,statistics
base=pathlib.Path('/tmp/logex-catalog-v3-base-bench')
candidate=pathlib.Path('/tmp/logex-live-bundle-integrated-candidate-bench')
profiles=[('few-logs',128,1,'historical',False),('tiny-chunks',2048,1,'historical',False),('sparse-history',8192,1,'historical',False),('short',128,128,'both',False),('sustained-history',2048,128,'historical',False),('large-history',512,1024,'historical',False),('per-block-live',128,128,'live',True),('one-row-live',128,1,'live',True),('rich-live',128,128,'live',True)]
with open('/tmp/logex-live-bundle-integrated-broad-broad-original-comparison.jsonl','w') as output:
 output.write(json.dumps({'kind':'build','base':'09a63f555db19a03850ce5eba6f149957febaf3b','candidate':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip() + ' plus captured diff','base_binary_sha256':hashlib.sha256(base.read_bytes()).hexdigest(),'candidate_binary_sha256':hashlib.sha256(candidate.read_bytes()).hexdigest(),'harness_change':'same v3 fixture inputs/oracles; original historical publication omitted fsync; candidate uses ordered progress publication with a bounded 32 MiB/64-call/5-second recovery window across pending/published work. Explicit checkpoint_durable is not requested. Per-block publication uses the same v3 fixture inputs; current adds a checkpoint call where original row-only writes already publish. Fresh live segments use bundles; known empty raw artifacts are removed on first-bundle retry. No sleeps. Exact clean reopen does not prove power-failure durability. No concurrent local builds/tests during timing.'})+'\n')
 output.write(json.dumps({'kind':'runner','source':pathlib.Path(__file__).read_text()})+'\n')
 for key,command in [('rustc',['rustc','-Vv']),('cargo',['cargo','-V']),('os',['sw_vers']),('kernel',['uname','-a']),('hardware',['sysctl','-n','hw.model','hw.memsize','hw.ncpu']),('filesystem_space',['df','-h','/private/tmp'])]:
  result=subprocess.run(command,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
  if result.returncode:raise RuntimeError(result.stdout)
  output.write(json.dumps({'kind':'environment','key':key,'output':result.stdout.strip()})+'\n')
 output.write(json.dumps({'kind':'source','candidate_worktree_diff':subprocess.check_output(['git','diff','HEAD'],text=True),'lockfile_sha256':hashlib.sha256(pathlib.Path('Cargo.lock').read_bytes()).hexdigest(),'fixture_sha256':hashlib.sha256(pathlib.Path('crates/logex-storage/tests/ingestion_publication.rs').read_bytes()).hexdigest(),'base_fixture_sha256':hashlib.sha256(pathlib.Path('/private/tmp/logex-publication-35p7tky4/base/crates/logex-storage/tests/ingestion_publication.rs').read_bytes()).hexdigest()})+'\n')
 for profile,blocks,rows,route,each in profiles:
  for pair in range(5):
   for label in (['base','candidate'] if pair%2==0 else ['candidate','base']):
    binary=base if label=='base' else candidate
    log=pathlib.Path(f'/tmp/logex-live-bundle-integrated-broad-broad-original-{profile}-{pair}-{label}.log')
    env=dict(os.environ,LOGEX_PUBLICATION_HEADER_FIELDS='rich' if profile.startswith('rich-') else 'minimal',LOGEX_PUBLICATION_BLOCKS=str(blocks),LOGEX_PUBLICATION_ROWS_PER_BLOCK=str(rows),LOGEX_PUBLICATION_HISTORY_BLOCKS='128' if profile in ['sustained-history','tiny-chunks'] else '2048',LOGEX_PUBLICATION_SEGMENT_ROWS='1000000',LOGEX_PUBLICATION_WARM_HEADERS='8192',LOGEX_PUBLICATION_REPEATS='3',LOGEX_PUBLICATION_ROUTE=route,LOGEX_PUBLICATION_CHECKPOINT_EACH_BLOCK=str(int(each)))
    with log.open('w') as capture:
     r=subprocess.run(['/usr/bin/time','-l',str(binary),'benchmark_sync_storage_publication','--ignored','--nocapture','--test-threads=1'],env=env,stdout=capture,stderr=subprocess.STDOUT)
    if r.returncode: raise RuntimeError(str(log)+': '+str(r.returncode))
    for line in log.read_text().splitlines():
     if '{' in line:
      try: record=json.loads(line[line.index('{'):])
      except json.JSONDecodeError: continue
      output.write(json.dumps({**record,'profile':profile,'revision':label,'pair':pair})+'\n')
     elif 'maximum resident set size' in line:
      output.write(json.dumps({'kind':'rss','profile':profile,'revision':label,'pair':pair,'bytes':int(line.split()[0])})+'\n')
    output.flush(); print(profile,pair,label,'passed',flush=True)
 records=[json.loads(line) for line in pathlib.Path('/tmp/logex-live-bundle-integrated-broad-broad-original-comparison.jsonl').read_text().splitlines()]
 for profile,*_ in profiles:
  metrics=sorted({r['metric'] for r in records if r.get('profile')==profile and r.get('kind')=='sample'})
  for metric in metrics:
   samples={label:[r['elapsed_ms'] for r in records if r.get('profile')==profile and r.get('kind')=='sample' and r.get('metric')==metric and r['revision']==label] for label in ['base','candidate']}
   medians={label:statistics.median(values) for label,values in samples.items()}
   summary={'kind':'summary','profile':profile,'metric':metric,'median_ms':medians,'change_percent':100*(medians['candidate']/medians['base']-1),'samples':{label:len(v) for label,v in samples.items()},'p95_ms':{label:sorted(v)[__import__('math').ceil(0.95*len(v))-1]for label,v in samples.items()}}
   output.write(json.dumps(summary)+'\n');print(summary,flush=True)

